<?php
$rows=db()->query("SELECT dp.*,u.nama,u.email,u.no_hp,u.status akun_status FROM data_pengurus dp JOIN users u ON u.id=dp.user_id ORDER BY dp.status='aktif' DESC,dp.jabatan,u.nama")->fetchAll();
$codes=db()->query('SELECT id,role,status,max_penggunaan,jumlah_digunakan,berlaku_sampai,created_at FROM access_codes ORDER BY created_at DESC LIMIT 20')->fetchAll();
?>
<div class="page-heading"><div><h1>Pengurus / RT</h1><p>Kelola perangkat RT dan terbitkan kode akses untuk calon Pengurus.</p></div></div>
<div class="row g-4 mb-4"><div class="col-xl-5"><section class="panel-card h-100"><div class="panel-card-header"><h2 class="panel-title">Buat Kode Akses Pengurus</h2></div><div class="panel-card-body"><p class="text-muted-2">Kode akses hanya dapat digunakan satu kali dan hanya ditampilkan saat dibuat.</p><form method="post" action="index.php" class="vstack gap-3"><?= csrf_field() ?><input type="hidden" name="action" value="create_access_code"><input type="hidden" name="return_page" value="pengurus"><div><label class="form-label">Berlaku sampai (opsional)</label><input class="form-control" type="datetime-local" name="berlaku_sampai"><div class="form-text">Kosongkan jika tidak ingin menetapkan tanggal kedaluwarsa.</div></div><button class="btn btn-army" type="submit"><i class="bi bi-key me-2"></i>Terbitkan Kode</button></form></div></section></div><div class="col-xl-7"><section class="panel-card h-100"><div class="panel-card-header"><h2 class="panel-title">Kode Akses Terbaru</h2><span class="text-muted-2 small">Kode asli tidak disimpan</span></div><div class="table-responsive"><table class="table"><thead><tr><th>Dibuat</th><th>Penggunaan</th><th>Status</th><th>Berlaku sampai</th><th>Aksi</th></tr></thead><tbody><?php if(!$codes): ?><tr><td colspan="5" class="text-center text-muted-2 py-4">Belum ada kode akses.</td></tr><?php else: foreach($codes as $c): ?><tr><td><?= e(format_date($c['created_at'])) ?></td><td><?= (int)$c['jumlah_digunakan'] ?> / <?= (int)$c['max_penggunaan'] ?></td><td><?= status_badge($c['status']) ?></td><td><?= e($c['berlaku_sampai']?format_datetime($c['berlaku_sampai']):'Tidak dibatasi') ?></td><td><?php if($c['status']==='aktif'): ?><form method="post" action="index.php"><?= csrf_field() ?><input type="hidden" name="action" value="revoke_access_code"><input type="hidden" name="return_page" value="pengurus"><input type="hidden" name="id" value="<?= $c['id'] ?>"><button class="btn btn-sm btn-outline-danger" data-confirm="Cabut kode akses ini?">Cabut</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div></section></div></div>
<section class="panel-card"><div class="panel-card-header"><h2 class="panel-title">Daftar Pengurus</h2><span class="text-muted-2 small"><?= count($rows) ?> pengurus</span></div><div class="table-responsive"><table class="table"><thead><tr><th>Nama</th><th>Jabatan</th><th>Wilayah</th><th>Email</th><th>Nomor HP</th><th>Status</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="6"><div class="empty-state"><i class="bi bi-person-badge"></i><strong>Belum ada Pengurus terdaftar</strong><span>Terbitkan kode akses lalu berikan kepada calon Pengurus untuk mendaftar.</span></div></td></tr><?php else: foreach($rows as $p): ?><tr><td><strong><?= e($p['nama']) ?></strong></td><td><?= e($p['jabatan']) ?></td><td><?= e('RT '.($p['rt']??'-').' / RW '.($p['rw']??'-')) ?></td><td><?= e($p['email']) ?></td><td><?= e($p['no_hp']??'-') ?></td><td><?= status_badge($p['status']) ?></td></tr><?php endforeach; endif; ?></tbody></table></div></section>
